using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using BankSystem.Shared.Infrastructure.Extensions;
using MassTransit;
using BankSystem.Reporting.Application.Interfaces;using BankSystem.Reporting.Infrastructure.Consumers;using BankSystem.Reporting.Infrastructure.Data;using BankSystem.Reporting.Infrastructure.Repositories;using Microsoft.EntityFrameworkCore;namespace BankSystem.Reporting.Infrastructure;public static class DependencyInjection{public static IServiceCollection AddInfrastructureServices(this IServiceCollection s,IConfiguration c){var cs=c.GetConnectionString("DefaultConnection")??throw new InvalidOperationException("DefaultConnection missing");s.AddDbContext<ReportingDbContext>(o=>o.UseNpgsql(cs));s.AddScoped<IReportRepository,ReportRepository>();s.AddMassTransitOutboxSupport<ReportingDbContext>(c,BankSystem.Shared.Kernel.Common.DatabaseEngine.PostgreSql,"Reporting",(bus,context)=>bus.ConfigureCrossServiceSubscription(context,"reporting","account",(endpoint,registrationContext)=>endpoint.ConfigureConsumer<AccountTransactionAppliedConsumer>(registrationContext)),config=>config.AddConsumer<AccountTransactionAppliedConsumer>());s.AddEnsureDatabaseCreated<ReportingDbContext>();s.AddEnsurePostgreSqlOutboxSchema<ReportingDbContext>();s.AddHostedService<ReportingSchemaUpgradeHostedService>();
        return s;}}
